using Microsoft.EntityFrameworkCore;
namespace Taply.Models;
public class TaplyDbContext(DbContextOptions<TaplyDbContext> options) : DbContext(options) { public DbSet<User> Users => Set<User>(); public DbSet<Place> Places => Set<Place>(); public DbSet<Page> Pages => Set<Page>(); public DbSet<PageSection> PageSections => Set<PageSection>(); public DbSet<PlaceSection> PlaceSections => Set<PlaceSection>(); protected override void OnModelCreating(ModelBuilder b) { b.Entity<User>().HasIndex(x=>x.Email).IsUnique(); b.Entity<Place>().HasIndex(x=>x.Slug).IsUnique(); b.Entity<Page>().HasIndex(x=>x.Slug).IsUnique(); b.Entity<Place>().HasOne(x=>x.User).WithMany(x=>x.Places).HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Cascade); b.Entity<Page>().HasOne(x=>x.Place).WithMany(x=>x.Pages).HasForeignKey(x=>x.PlaceId).OnDelete(DeleteBehavior.Cascade); b.Entity<PageSection>().HasOne(x=>x.Page).WithMany(x=>x.Sections).HasForeignKey(x=>x.PageId).OnDelete(DeleteBehavior.Cascade); b.Entity<PlaceSection>().HasOne(x=>x.Place).WithMany(x=>x.SharedSections).HasForeignKey(x=>x.PlaceId).OnDelete(DeleteBehavior.Cascade); } }
